INSERT INTO candidate_facts (id,qualification_id,provider_id,exam_level_id,exam_component,delivery_mode,payment_method,exam_year,fact_key,value_type,normalized_value,display_value,evidence_text,status,risk_level,source_id,source_snapshot_id,synthetic,created_at) VALUES ('candidate:gyoseishoshi:e634d0296d1ded3352a3684c352114f0a24d25a7a10c167a32f8028d1d600ecd:exam_subjects','qualification:gyoseishoshi',NULL,NULL,NULL,NULL,NULL,2026,'exam_subjects','text'::fact_value_type,'"行政書士の業務に関し必要な法令等・行政書士の業務に関し必要な基礎知識"'::jsonb,'行政書士の業務に関し必要な法令等（出題数４６題） 憲法、行政法（行政法の一般的な法理論、行政手続法、行政不服審査法、行政事件訴訟法、国家賠償法及び地方自治法を中心とする。）、民法、商法及び基礎法学の中からそれぞれ出題し、法令については、令和８年４月１日現在施行されている法令に関して出題します。 / 行政書士の業務に関し必要な基礎知識（出題数１４題） 一般知識、行政書士法等行政書士業務と密接に関連する諸法令、情報通信・個人情報保護及び文章理解の中からそれぞれ出題し、法令については、令和８年４月１日現在施行されている法令に関して出題します。','行政書士の業務に関し必要な法令等（出題数４６題） 憲法、行政法（行政法の一般的な法理論、行政手続法、行政不服審査法、行政事件訴訟法、国家賠償法及び地方自治法を中心とする。）、民法、商法及び基礎法学の中からそれぞれ出題し、法令については、令和８年４月１日現在施行されている法令に関して出題します。 / 行政書士の業務に関し必要な基礎知識（出題数１４題） 一般知識、行政書士法等行政書士業務と密接に関連する諸法令、情報通信・個人情報保護及び文章理解の中からそれぞれ出題し、法令については、令和８年４月１日現在施行されている法令に関して出題します。','approved','high'::risk_level,'source:gyoseishoshi:guide','snapshot:gyoseishoshi:e634d0296d1ded3352a3684c352114f0a24d25a7a10c167a32f8028d1d600ecd',false,'2026-01-01T00:00:00.000Z'::timestamptz);
INSERT INTO candidate_facts (id,qualification_id,provider_id,exam_level_id,exam_component,delivery_mode,payment_method,exam_year,fact_key,value_type,normalized_value,display_value,evidence_text,status,risk_level,source_id,source_snapshot_id,synthetic,created_at) VALUES ('candidate:gyoseishoshi:e634d0296d1ded3352a3684c352114f0a24d25a7a10c167a32f8028d1d600ecd:exam_time','qualification:gyoseishoshi',NULL,NULL,NULL,NULL,NULL,2026,'exam_time','integer'::fact_value_type,'"180"'::jsonb,'試験時間 午後１時から午後４時まで','試験時間 午後１時から午後４時まで','approved','high'::risk_level,'source:gyoseishoshi:guide','snapshot:gyoseishoshi:e634d0296d1ded3352a3684c352114f0a24d25a7a10c167a32f8028d1d600ecd',false,'2026-01-01T00:00:00.000Z'::timestamptz);
