INSERT INTO fact_revisions (id,candidate_fact_id,status,normalized_value,display_value,valid_from,verified_at,idempotency_key) VALUES ('revision:candidate:bookkeeping:6a49427fcc0b9ae0f07a90f3381e41e88b06704115d155d5fcdb16d5d4800500:bookkeeping:3:network:statistics_methodology:98f76b0bbf3f','candidate:bookkeeping:6a49427fcc0b9ae0f07a90f3381e41e88b06704115d155d5fcdb16d5d4800500:bookkeeping:3:network:statistics_methodology:98f76b0bbf3f','approved','"2020年12月に開始した日商簿記検定試験2級・3級ネット試験の受験者データは、以下のとおりです。 ※2021年度から、統一試験、団体試験（ペーパー試験）、ネット試験方式で施行しております。試験問題について、3方式いずれも出題範囲や問題の難易度は同じです（新たな日商簿記検定のイメージをご参照ください）。"'::jsonb,'2020年12月に開始した日商簿記検定試験2級・3級ネット試験の受験者データは、以下のとおりです。 ※2021年度から、統一試験、団体試験（ペーパー試験）、ネット試験方式で施行しております。試験問題について、3方式いずれも出題範囲や問題の難易度は同じです（新たな日商簿記検定のイメージをご参照ください）。','2026-01-01T00:00:00.000Z'::timestamptz,'2026-01-01T00:00:00.000Z'::timestamptz,'ci:candidate:bookkeeping:6a49427fcc0b9ae0f07a90f3381e41e88b06704115d155d5fcdb16d5d4800500:bookkeeping:3:network:statistics_methodology:98f76b0bbf3f');
